const WATER_CLOCK_INFO={id:"water-clocks",title:"Ghati Yantra — The Indian Water Clock",originRegion:"Indian Subcontinent",eraOrigin:"c. 1500 BCE, refined through the Vedic & Medieval periods",unitOfTime:"1 Ghati ≈ 24 minutes (60 Ghatis = 1 day)",quickStats:[{label:"Also Known As",value:"Ghati Yantra / Kapala Yantra",icon:"💧"},{label:"Time Unit",value:"1 Ghati ≈ 24 minutes",icon:"⏱️"},{label:"Earliest Use",value:"c. 1500 BCE",icon:"🏺"},{label:"Mechanism",value:"Sinking Copper Bowl",icon:"🥣"},{label:"Still Used In",value:"Temples & Traditional Rituals",icon:"🛕"},{label:"Global Cousin",value:"Egyptian & Greek Clepsydra",icon:"🌍"}]},HISTORY_TEXT={title:"From Vedic Rituals to Royal Courts",paragraphs:["Water clocks, known in India as Ghati Yantra or Kapala Yantra, are among the oldest known timekeeping devices, with references dating back to the Vedic period (c. 1500 BCE). They were essential for scheduling religious rituals (yajnas), which required precise timing.","The most common Indian design used a small hemispherical copper bowl (kapala) with a tiny hole in its base, floated on the surface of a larger vessel filled with water. Water seeped in gradually through the hole, and when the bowl finally filled and sank, it marked the passage of one 'ghati' — roughly 24 minutes.","A person, often a temple attendant called a 'ghatika', would strike a gong or bell each time the bowl sank, announcing the time to the community. This system remained in use in many Indian temples and royal courts well into the 19th century, alongside the spread of mechanical clocks."]},SCIENTIFIC_PRINCIPLES=[{title:"Constant Inflow Rate",description:"The hole's fixed diameter combined with near-constant water pressure allowed water to seep in at a predictable rate, making the timing repeatable."},{title:"Buoyancy & Displacement",description:"The bowl floats due to buoyant force until enough water enters to make its weight exceed the displaced water's weight, at which point it sinks — a simple, direct application of Archimedes' principle."},{title:"Calibration by Volume",description:"Astronomers calibrated the size of the hole and bowl against known solar-day observations, effectively dividing a day into 60 equal ghatis."},{title:"Self-Regulating Cycle",description:"Once the bowl sank, it was emptied and re-floated, creating a repeatable, self-resetting cycle that needed no external power source."}],COMPARISON_ROWS=[{aspect:"Power Source",ancient:"Gravity & water flow (no external power)",modern:"Electricity, batteries, or mechanical springs"},{aspect:"Precision",ancient:"Approximate — accurate to a few minutes per cycle",modern:"Accurate to milliseconds or better (quartz/atomic)"},{aspect:"Portability",ancient:"Mostly fixed installations (temples, courts)",modern:"Highly portable (wristwatches, phones)"},{aspect:"Maintenance",ancient:"Manual refilling, emptying, and observation",modern:"Largely self-maintaining"},{aspect:"Environmental Sensitivity",ancient:"Affected by water temperature, evaporation, sediment",modern:"Largely unaffected by environment"},{aspect:"Primary Use",ancient:"Ritual timing, court schedules, night watches",modern:"Universal personal & industrial timekeeping"}],REFERENCES=[{text:"Needham, J. — 'Science and Civilisation in China, Vol. 3' (comparative clepsydra study).",link:"#"},{text:"Sarma, S. R. — 'Yantras (Instruments) for Astronomy and Time Measurement in India.'",link:"#"},{text:"Ohashi, Y. — 'Astronomical Instruments in Classical Siddhantas.'",link:"#"},{text:"National Council of Science Museums, India — Timekeeping Instruments Gallery.",link:"#"}];